INSERT INTO `pet_gamification_actions` (`id`, `action_key`, `custom_message`, `notification_message`, `points`, `created_at`) VALUES
(2, 'user_register', 'User will get 30 points for registration.', 'You have earned {points} points for registration', 30, '2025-09-24 13:11:46'),
(3, 'first_login', 'You will earn 10 points for first time login. You will get 2 points for daily login.', 'You have received {points} points for first time login. You will get 2 points for daily login.', 10, '2025-09-24 13:59:51'),
(4, 'profile_picture_update', 'You will earn 10 points for updating your profile picture!', 'You have earned {points} points for updating your profile picture!', 10, '2025-09-24 14:00:54'),
(7, 'cover_photo_update', 'You will earn 10 points for updating your cover picture!', 'You have earned {points} points for cover photo upload.', 10, '2025-11-19 09:52:47'),
(8, 'daily_login', 'You will be earn 2 points for daily login!', 'Welcome back! You have earned {points} points for your daily login.', 2, '2025-11-19 16:16:40'),
(10, 'birthday_update', 'You will earn 10 points once you update your birthday for first time.', 'You have received {points} points for birthday update.', 10, '2025-11-26 03:10:39'),
(11, 'location_update', 'You will earn 10 points once you update your location.', 'You have received {points} points for location update.', 10, '2025-11-26 03:11:25');
