(79, 1, '2025-04-11 17:44:21', '2025-04-11 17:44:21', '<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Zoom Q&amp;A: Wednesday 7 pm PST</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>The Meeting ID is: </strong><br>898 0870 9066 and <br><strong>Passcode is:</strong><br>fuT8WG<br><strong>Meeting Join URL:</strong><br>https://us06web.zoom.us/j/89808709066?pwd=zMhE6bX0gI9uqMycCwXjEeUTkKQMBj.1</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:embed {\"url\":\"https://youtu.be/4TBbuwTqBgw?si=LIlI-Bk9hXv6Q36J\",\"type\":\"video\",\"providerNameSlug\":\"youtube\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://youtu.be/4TBbuwTqBgw?si=LIlI-Bk9hXv6Q36J\n</div></figure>\n<!-- /wp:embed --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:html -->\n<section class=\"bg-gradient-to-r from-purple-600 to-indigo-700 text-white rounded-xl p-8 max-w-3xl mx-auto my-10 shadow-2xl\">\n  <h2 class=\"text-2xl font-bold mb-4\">Q&amp;A Intro:<br/> <span class=\"text-yellow-300\">See Why an Empowerment Team Will Change Your Life</span></h2>\n  \n  <div class=\"bg-white text-gray-900 rounded-xl p-6 shadow-inner space-y-2\">\n    <p><strong>📅 Z