(118, 1, '2025-04-11 18:41:23', '2025-04-11 18:41:23', '<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:html -->\n<section class=\"bg-black text-white rounded-xl p-8 max-w-3xl mx-auto my-10 shadow-2xl\">\n  <div class=\"mb-6\">\n    <h2 class=\"text-3xl font-bold mb-2\">\n      See Why an Empowerment Team Will Change Your Life\n    </h2>\n    <p class=\"text-lg text-yellow-300 font-semibold\">\n      📅 Zoom Q&amp;A: Wednesday 7 PM PST\n    </p>\n  </div>\n\n  <div class=\"rounded-xl p-6 space-y-3 border border-gray-700\">\n    <p>\n      <strong class=\"text-indigo-400\">Meeting ID:</strong>\n      <span class=\"font-mono bg-gray-800 px-2 py-1 rounded text-sm\">898 0870 9066</span>\n    </p>\n\n    <p>\n      <strong class=\"text-indigo-400\">Passcode:</strong>\n      <span class=\"font-mono bg-gray-800 px-2 py-1 rounded text-sm\">fuT8WG</span>\n    </p>\n\n    <div class=\"pt-4\">\n      <a\n        href=\"https://us06web.zoom.us/j/89808709066?pwd=zMhE6bX0gI9uqMycCwXjEeUTkKQMBj.1\"\n        target=\"_blank\"\n        class=\"inline-block px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-lg shadow-lg transition\"\n      >\n        🔗 Join Zoom Meeting\n      </a>\n    </div>\n  </div>\n</section>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:html /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:esab/accordion {\"uniqueId\":\"esab-6787uc8k\",\"blockStyle\":\" .esab-6787uc8k.wp-block-esab-accordion, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion{margin: 0px;} .esab-6787uc8k.wp-block-esab-accordion \\u003e .esab__container, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion \\u003e .esab__container{gap:10px;} .esab-6787uc8k.wp-block-esab-accordion .esab__container \\u003e .wp-block-esab-accordion-child, .esab-6787uc8k.wp