(127, 1, '2025-04-11 18:49:08', '2025-04-11 18:49:08', '<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:html -->\n<section class=\"text-white max-w-3xl my-10\">\n  <div class=\"mb-6\">\n    <h2 class=\"text-6xl font-bold mb-2\">\n      See Why an <span class=\"text-yellow-500\">Empowerment Team</span><br/> Will Change Your Life\n    </h2>    \n  </div>\n\n  <div class=\"rounded-xl p-6 border border-gray-700\">\n<p class=\"text-lg text-yellow-300 font-semibold\">\n      📅 Zoom Q&amp;A: Wednesday 7 PM PST\n    </p>\n    <p>\n      <strong class=\"text-indigo-400\">Meeting ID:</strong>\n      <span class=\"font-mono bg-gray-800 px-2 py-1 rounded text-sm\">898 0870 9066</span>\n    </p>\n\n    <p>\n      <strong class=\"text-indigo-400\">Passcode:</strong>\n      <span class=\"font-mono bg-gray-800 px-2 py-1 rounded text-sm\">fuT8WG</span>\n    </p>\n\n    <div class=\"pt-4\">\n      <a\n        href=\"https://us06web.zoom.us/j/89808709066?pwd=zMhE6bX0gI9uqMycCwXjEeUTkKQMBj.1\"\n        target=\"_blank\"\n        class=\"inline-block px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-lg shadow-lg transition\"\n      >\n        🔗 Join Zoom Meeting\n      </a>\n    </div>\n  </div>\n</section>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:html /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:esab/accordion {\"uniqueId\":\"esab-6787uc8k\",\"blockStyle\":\" .esab-6787uc8k.wp-block-esab-accordion, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion{margin: 0px;} .esab-6787uc8k.wp-block-esab-accordion \\u003e .esab__container, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion \\u003e .esab__container{gap:10px;} .esab-6787uc8k.wp-block-esab-accordion .esab__container \\u003e .wp-block-esab-accordion-child, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .esab__container \\u003e .wp-block-esab-accordion-child, .esab-6787uc8k.wp-block-esab-accordion .block-editor-block-list__block \\u003e .wp-block-esab-accordion-child, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .block-editor-block-list__block \\u003e .wp-block-esab-accordion-child{border-style: solid;border-color: #E0E0E0;border-width: 1px;border-radius: 3px;} .esab-6787uc8k.wp-block-esab-accordion .esab__container \\u003e .wp-block-esab-accordion-child.esab__active_accordion, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .esab__container \\u003e .wp-block-esab-accordion-child.esab__active_accordion, .esab-6787uc8k.wp-block-esab-accordion .block-editor-block-list__block \\u003e .wp-block-esab-accordion-child.esab__active_accordion, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .block-editor-block-list__block \\u003e .wp-block-esab-accordion-child.esab__active_accordion{border-color:#3fa796;} .esab-6787uc8k.wp-block-esab-accordion .wp-block-esab-accordion-child \\u003e .esab__head, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .wp-block-esab-accordion-child \\u003e .esab__head{padding: 10px;gap:8px;} .esab-6787uc8k.wp-block-esab-accordion .esab__active_accordion \\u003e .esab__head, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .esab__active_accordion \\u003e .esab__head{background:#f0fffd;} .esab-6787uc8k.wp-block-esab-accordion .esab__active_accordion .esab__heading_txt \\u003e .esab__heading_tag, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .esab__active_accordion .esab__heading_txt \\u003e .esab__heading_tag{color:#3fa796;} .esab-6787uc8k.wp-block-esab-accordion .wp-block-esab-accordion-child \\u003e .esab__head .esab__icon svg, .esab-6787uc8k.wp-block-esab-accordion.nested-accordion .wp-block-esab-accordion-child \\u003e .esab__head .esab__icon svg{font-size:20px;} .esab-6787uc8k.wp-block-esab-accordion .wp-block-esab-accordion-child \\u003e .esab__head .esab__icon img,