INSERT INTO `pet_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(173, 1, '2025-04-16 15:08:22', '2025-04-16 15:08:22', '<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:html -->\n<div class=\"relative w-full h-auto aspect-[3/2]\">\n  <img src=\"http://pet.test/wp-content/uploads/2025/04/pexels-mikael-blomkvist-6476774-scaled.jpg\" alt=\"Video Thumbnail\" class=\"object-cover w-full h-full rounded-xl shadow-md\">\n  <a class=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 video-popup-btn\" href=\"https://www.youtube.com/watch?v=4TBbuwTqBgw\" target=\"_blank\" aria-label=\"Watch Video\">\n    <div class=\"relative group\">\n      <span class=\"absolute inline-flex h-full w-full rounded-full bg-red-500 opacity-75 group-hover:opacity-90 slow-ping\"></span>\n      <div class=\"relative z-10 flex items-center justify-center w-12 h-12 md:w-16 md:h-16 bg-red-600 text-white rounded-full shadow-lg group-hover:scale-110 transition-transform duration-300\">\n        <svg class=\"w-5 h-5 md:w-6 md:h-6\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n          <path d=\"M6 4l12 6-12 6V4z\" />\n        </svg>\n      </div>\n    </div>\n  </a>\n</div>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:html -->\n<section class=\"text-white max-w-3xl\">\n  <div class=\"mb-6\">\n    <h2 class=\"text-6xl font-bold mb-2 leading-tight\">\n      See Why an <span class=\"text-yellow-500\">Empowerment Team</span><br/> Will Change Your Life\n    </h2>    \n  </div>\n\n  <div class=\"rounded-xl border border-gray-900\">\n<p class=\"text-lg text-yellow-300 font-semibold\">\n      📅 Zoom Q&amp;A: Wednesday 7 PM PST\n    </p>\n    <p>\n      <strong class=\"text-indigo-400\">Meeting ID:</strong>\n      <span class=\"font-mono bg-gray-800 px-2 py-1 rounded text-sm\">898 0870 9066</span>\n    </p>\n\n    <p>\n      <strong class=\"text-indigo-400\">Passcode:</strong>\n      <span class=\"font-mono bg-gray-800 px-2 py-1 rounded text-sm\">fuT8WG</span>\n    </p>\n\n    <div class=\"pt-4\">\n      <a\n        href=\"https://us06web.zoom.us/j/89808709066?pwd=zMhE6bX0gI9uqMycCwXjEeUTkKQMBj.1\"\n        target=\"_blank\"\n        class=\"inline-block px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-lg shadow-lg transition\"\n      >\n        🔗 Join Zoom Meeting\n      </a>\n    </div>\n  </div>\n</section>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:coblocks/accordion -->\n<div class=\"wp-block-coblocks-accordion\"><!-- wp:coblocks/accordion-item {\"title\":\"\\u003cstrong\\u003eWhat are Zoom Q\\u0026amp;A Intros about? \\u003c/strong\\u003e\"} -->\n<div class=\"wp-block-coblocks-accordion-item\"><details><summary class=\"wp-block-coblocks-accordion-item__title\"><strong>What are Zoom Q&amp;A Intros about? </strong></summary><div class=\"wp-block-coblocks-accordion-item__content\"><!-- wp:paragraph {\"placeholder\":\"Add content…\"} -->\n<p>The Q&amp;A Intro is to help you determine whether you want to participate in an Empowerment Team or not. Goals are challenging, so we want you to confirm that you are committing to your dreams and that you are 100% All In. </p>\n<!-- /wp:paragraph --></div></details></div>\n<!-- /wp:coblocks/accordion-item -->\n\n<!-- wp:coblocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003eAre there any costs to participate?\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<div class=\"wp-block-coblocks-accordion-item\"><details><summary class=\"wp-block-coblocks-accordion-item__title\"><strong><strong><strong>Are there any costs to participate?</strong></strong></strong></summary><div class=\"wp-block-coblocks-accordion-item__content\"><!-- wp:paragraph {\"placeholder\":\"Add content…\"} -->\n<p>We\'ll support you in becoming who and what you always wanted to be.</p>\n<!-- /wp:paragraph --></div></details></div>\n<!-- /wp:coblocks/accordion-item -->\n\n<!-- wp:coblocks/accordion-item {\"title\":\"\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003e\\u003cstrong\\u003eWhat will I gain from Empowerment Teams?\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\\u003c/strong\\u003e\"} -->\n<div class=\"wp-block-coblocks-accordion-item\"><details><summary class=\"wp-block-coblocks-accordion-item__title\"><strong><strong><strong><strong>What will I gain from Empowerment Teams?</strong></strong></strong></strong></summary><div class=\"wp-block-coblocks-accordion-item__content\"><!-- wp:paragraph {\"placeholder\":\"Add content…\"} -->\n<p>We\'ll support you in becoming who and what you always wanted to be.</p>\n<!-- /wp:paragraph --></div></details></div>\n<!-- /wp:coblocks/accordion-item --></div>\n<!-- /wp:coblocks/accordion -->\n\n<!-- wp:html -->\n<div class=\"wp-block-esab-accordion esab-6787uc8k\" data-mode=\"global\"><div class=\"esab__container\">\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>What are Zoom Q&amp;A Intros about? </strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<p>The Q&amp;A Intro is to help you determine whether you want to participate in an Empowerment Team or not. Goals are challenging, so we want you to confirm that you are committing to your dreams and that you are 100% All In.&nbsp;</p>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong><strong>Are there any costs to participate?</strong></strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<p>There are no costs for the first 10 team members. Contributions are at individual\'s discretion.</p>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>What will I gain from Empowerment Teams?</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<p>We\'ll support you in becoming who and what you always wanted to be.</p>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>What\'s expected of me from your P. E. Teams?</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<ul class=\"wp-block-list\">\n<li>You are expected to learn and embrace your responsibility to the success of your short, mid, and long-term commitments to yourself.</li>\n<li>Discover your power beyond measure.</li>\n<li>Discover and dissolve your barriers so you can become who and what you want to be this year.</li>\n</ul>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>Priority #1 is Empowering You</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<ul class=\"wp-block-list\">\n<li>Our #1 priority is empowering our members, including careers, health, diabetes, relationships, addictions, resolutions, and others.</li>\n<li>Personal Empowerment Teams, Inc. is a non-profit empowerment community dedicated to the well-being of members like you to Become Who &amp; What You Want To Be.</li>\n<li>We are not motivational speakers, thus we do not focus on quick motivational seminars.</li>\n<li>Personal Empowerment Teams are part of a greater whole to empower people long lasting self-mastery; including community, employment, housing, equity, and profit-sharing.</li>\n<li>People sign up for short, and long-term commitments to locate their power beyond measure and discover and dissolve their barriers so they can become who and what they want to be this year.</li>\n<li>Each team process is its own magic to get through barriers (habits, fears, inner pain, addictions, diabetes, relationships, careers, depression, poverty, etc), and to step into your power to become who and what you always wanted to be.</li>\n<li>Personal Empowerment Teams consist of like-minded trainers, friends, and coaches with similar goals.</li>\n<li>Each team member seeks specific change/s and therefore has specific commitments to becoming who and what they want to be this year.</li>\n</ul>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>Three Steps to Mastery</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<ul class=\"wp-block-list\">\n<li><strong>Legacy Retreat: Full-Day</strong>&nbsp;<strong>Retreat</strong>&nbsp;in Sherman Oaks, California.&nbsp;<strong>The Legacy Retreat</strong>, will reconnect &amp; activate your true legacy of present, past, future, omniscience, omnipresence, and omnipotence. You will Clarify &amp; Commit to Who and What You Want To Be This Year.</li>\n<li><strong>Preparation For Mastery:</strong>&nbsp;Consists of three (2-hour) Teamwork Meetings over three weeks, to prepare you for your Mastery Course and beyond.</li>\n<li><strong>Mastery Course:</strong>&nbsp;Consists of one (2-hour) weekly meeting for 90 Days to Master Who and What You Want To Be this year. You\'ll learn, practice, and master; support, mirroring, brainstorming, goal setting, and goal management for all changes &amp; commitments. Individual breakthroughs are achieved within each team’s safe space, confidentiality, and care. The Mastery Course prepares you to Become Who and What You Want To Be This Year.&nbsp;</li>\n</ul>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>Graduations &amp; Perks</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<ul class=\"wp-block-list\">\n<li>Certification specialties are listed in our curriculum.</li>\n<li>Certified graduates can advance into leadership.</li>\n<li>Certified graduates can work as salary &amp;/or commission staff on a profitability basis.</li>\n<li>Graduates can exit or stay with their teams indefinitely, and/or move around within the organization.</li>\n</ul>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>Certification Curriculum</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<ul class=\"wp-block-list\">\n<li>Life Coaching</li>\n<li>Communications Coaching</li>\n<li>Leadership &amp; Executive Coaching</li>\n<li>Career Coaching</li>\n<li>Entrepreneurial &amp; Business Coaching</li>\n<li>Life Transitions &amp; Resilience Coaching</li>\n<li>Confidence &amp; Self-Esteem Coaching</li>\n<li>Emotional Intelligence (EQ) Coaching</li>\n<li>Spiritual &amp; Purpose Coaching</li>\n<li>Stress &amp; Mindfulness Coaching</li>\n<li>Relationship Coaching</li>\n<li>Parenting &amp; Family Coaching</li>\n<li>Fitness, Health &amp; Weight Loss Coaching</li>\n<li>Diabetes Coaching (does not replace medical care)</li>\n<li>Addictions Coaching (diagnosis, addiction treatment &amp; therapy requires license)</li>\n<li>Financial Breakthroughs Coaching (excludes investments or taxes)</li>\n<li>Trauma-informed coaching (does not replace clinical therapy)</li>\n</ul>\n</div></div>\n<div class=\"wp-block-esab-accordion-child\"><div class=\"esab__head\" role=\"button\" aria-expanded=\"false\"><div class=\"esab__heading_txt\"><p class=\"esab__heading_tag\"><strong>If You\'re Serious about You *</strong></p></div><div class=\"esab__icon\"><div class=\"esab__collapse\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m3.5 20.5c-4.7-4.7-4.7-12.3 0-17 4.7-4.7 12.3-4.7 17 0 4.6 4.7 4.6 12.3 0 17-4.7 4.6-12.3 4.6-17 0zm0.9-0.9c4.2 4.2 11 4.2 15.2 0 4.2-4.2 4.2-11 0-15.2-4.2-4.3-11-4.3-15.2 0-4.3 4.2-4.3 11 0 15.2z\"></path><path d=\"m11.4 15.9v-3.3h-3.3c-0.3 0-0.6-0.3-0.6-0.6 0-0.4 0.3-0.6 0.6-0.6h3.3v-3.3c0-0.3 0.3-0.6 0.6-0.6 0.3 0 0.6 0.3 0.6 0.6v3.3h3.3c0.3 0 0.6 0.2 0.6 0.6q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2h-3.3v3.3q0 0.2-0.2 0.4-0.2 0.2-0.4 0.2c-0.4 0-0.6-0.3-0.6-0.6z\"></path></svg> </div><div class=\"esab__expand\"> <svg version=\"1.2\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path fill-rule=\"evenodd\" d=\"m12 24c-6.6 0-12-5.4-12-12 0-6.6 5.4-12 12-12 6.6 0 12 5.4 12 12 0 6.6-5.4 12-12 12zm10.6-12c0-5.9-4.7-10.6-10.6-10.6-5.9 0-10.6 4.7-10.6 10.6 0 5.9 4.7 10.6 10.6 10.6 5.9 0 10.6-4.7 10.6-10.6z\"></path><path d=\"m5.6 11.3h12.8v1.4h-12.8z\"></path></svg> </div></div></div><div class=\"esab__body\">\n<p>Learn how the champions and billionaires do it, and master the tools to become who &amp; what you want to be this year.</p>\n<p>✅ Transform yourself and others.<br>✅ We’ll certify you in the Certifications listed in our Curriculum.<br>✅ Meet and brainstorm with like-minded trainers, friends, and coaches.<br>✅Enjoy Meaningful Times around your priorities and have the time of your life!</p>\n<p><strong>But what if you don\'t have an Empowerment Team? *</strong> </p>\n<p>I’m Joseph, of Personal Empowerment Teams and author of&nbsp;<em>Legacy Portal.</em>&nbsp;</p>\n<p>Empowerment Teams helped me:<br>✔ Overcome poverty &amp; addiction<br>✔ Increase my income from $40K annually to $120K monthly (earning $3.5M by age 47)<br>✔ Lower my A1C from 13+ to under 6<br>✔ Lost 60 pounds after recovering from a near-death car accident<br>✔ They helped me build a Paradigm Shift for me and others to make the world a better place *</p>\n</div></div>\n</div></div>\n<!-- /wp:html -->', 'Q&amp;A Intro: See Why an Empowerment Team Will Change Your Life', '', 'inherit', 'closed', 'closed', '', '18-revision-v1', '', '', '2025-04-16 15:08:22', '2025-04-16 15:08:22', '', 18, 'http://pet.test/?p=173', 0, 'revision', '', 0),
