(279, 1, '2025-05-02 05:56:09', '2025-05-02 05:56:09', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"60%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:60%\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Empowerment Teams, and 100+ Referral &amp; Funding Tools for Startups &amp; Comebacks</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\">We Revive Souls &amp; Fund Lives Through Small Teams &amp; Our Nonprofit Empowerment Platform</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"marginabove-30\"} -->\n<div class=\"wp-block-columns marginabove-30\"><!-- wp:column {\"width\":\"35%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:35%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"30%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:30%\"><!-- wp:html -->\n<a href=\"/signup\" class=\"btn-get-started\">Get Started</a>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"35%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:35%\"><!-- wp:html -->\n<div class=\"mobile-mtmb\"><img src=\"https://personalempowermentteams.me/wp-content/uploads/2025/10/Rating-Container-2.png\" alt=\"24/7 Empowerment Ratings\" /></div>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":838,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://personalempowermentteams.me/wp-content/uploads/2025/10/image-5-2-1_imgupscaler.ai_v1Fast_4K-2-2.png\" alt=\"\" class=\"wp-image-838\"/></figure>\n<!-- /wp:image -->', 'Welcome', '', 'publish', 'closed', 'closed', '', 'welcome', '', '', '2025-10-20 17:27:09', '2025-10-20 17:27:09', '', 0, 'http://pet.test/?page_id=279', 0, 'page', '', 0),
